#[cfg(test)]
mod execution_report_tests {
    use super::*;
    use crate::extend_200115::*;
    use crate::extend_200215::*;
    use crate::extend_200315::*;
    use crate::extend_200515::*;
    use crate::extend_200615::*;
    use crate::extend_200715::*;
    use crate::extend_203715::*;
    use crate::extend_204115::*;
    use crate::extend_204130::*;
    use crate::extend_204715::*;
    use crate::extend_206315::*;
    use bytes::BytesMut;

    #[test]
    fn test_execution_report_codec() {
        let mut original = ExecutionReport {
            partition_no: -123456,
            report_index: -123456789,
            reporting_pbuid: "a".repeat(6),
            submitting_pbuid: "a".repeat(6),
            security_id: "a".repeat(8),
            security_id_source: "a".repeat(4),
            owner_type: 1234,
            clearing_firm: "a".repeat(2),
            transact_time: -123456789,
            user_info: "a".repeat(8),
            order_id: "a".repeat(16),
            cl_ord_id: "a".repeat(10),
            quote_msg_id: "a".repeat(10),
            exec_id: "a".repeat(16),
            exec_type: "a".to_string(),
            ord_status: "a".to_string(),
            last_px: -123456789,
            last_qty: -123456789,
            leaves_qty: -123456789,
            cum_qty: -123456789,
            side: "a".to_string(),
            account_id: "a".repeat(12),
            branch_id: "a".repeat(4),
            appl_id: "010".to_string(),
            appl_extend: ExecutionReportApplExtendEnum::Extend200115(Extend200115 {
                cash_margin: "a".to_string(),
            }),
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let bytes = buf.freeze();
        assert!(ExecutionReportRef::from_slice(&bytes).is_some());
        let mut reuse_bytes = bytes.clone();
        let mut reused = original.clone();
        ExecutionReport::decode_into(&mut reuse_bytes, &mut reused).unwrap();
        let mut bytes = bytes;

        let decoded = ExecutionReport::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
        assert_eq!(original, reused);
    }
}

